# So due to the fact that the coconut entries are incomplete I am going to use the API and reclassify the stuff

dfcompounds  = pd.read_csv('ANPDB/anpdb_compounds_for_dbclean.csv')
dfpathways   = pd.read_csv('/home/school/masters/Scripts/NpClassifier_ClassyFire/NpClassifierPathwaysDB.csv')
dfsuperclass = pd.read_csv('/home/school/masters/Scripts/NpClassifier_ClassyFire/NpClassifierSuperclassesDB.csv')
dfclasses    = pd.read_csv('/home/school/masters/Scripts/NpClassifier_ClassyFire/NpClassifierClassesDB.csv')

def progress_bar(count, length):
    bar_length = 40
    filled_length = int(bar_length * count // length)
    bar = '#' * filled_length + '-' * (bar_length - filled_length)
    print(f'\rProgress: |{bar}| {count}/{length} ({(count/length)*100:.2f}%)', end='')

url = 'https://npclassifier.gnps2.org/classify?smiles=<smiles string>'


"""r = requests.get(url.replace('<smiles string>', 'CCC1=NC=CN=C1C(C)=O'), timeout=10)
r.raise_for_status()
data = r.json()
print(data)
print(data['class_results'])"""

counter = 0
errors = []
entry_pathway = []
entry_superclass = []
entry_class = []
classes = set(dfclasses['class'].values)
superclasses = set(dfsuperclass['superclass'].values)
pathways = set(dfpathways['pathway'].values)

noclasses = []
nosuperclasses = []
nopathways = []
errors_from_requests = []

issueIDs = []

newclasses = set()
newsuperclasses = set()
newpathways = set()

for compound_id, smiles in dfcompounds[['compound_id','smiles']].values:
    counter += 1
    time.sleep(0.5)
    try:
        r = requests.get(url.replace('<smiles string>', smiles))
        r.raise_for_status()
        data = r.json()
        classres      = data['class_results']
        superclassres = data['superclass_results']
        pathwayres    = data['pathway_results']
        
        if not classres:
            noclasses.append(compound_id)
        else:
            if classres[0] not in classes:
                newclasses.add(classres[0])
                issueIDs.append(compound_id)
                errors.append(f"No class for {classres}")
                print(f"No class for {classres}")
            else:    
                classid = int(dfclasses[dfclasses['class'] == classres[0]]['class_id'].iloc[0])
                entry_class.append((compound_id, classid))

        if not superclassres:
            nosuperclasses.append(compound_id)
        else:
            for superclass in superclassres:
                if superclass not in superclasses:
                    newsuperclasses.add(superclass)
                    issueIDs.append(compound_id)
                    errors.append(f"No superclass for {superclass}")
                    print(f"No superclass for {superclass}")
                else:
                    superclassid = int(dfsuperclass[dfsuperclass['superclass'] == superclass]['superclass_id'].iloc[0])
                    entry_superclass.append((compound_id, superclassid))

        if not pathwayres:
            nopathways.append(compound_id)
        else:                    
            for pathway in pathwayres:
                if pathway not in pathways:
                    newpathways.add(pathway)
                    issueIDs.append(compound_id)
                    errors.append(f"No pathway for {pathway}")
                    print(f"No pathway for {pathway}")
                else:
                    pathwayid = int(dfpathways[dfpathways['pathway'] == pathway]['pathway_id'].iloc[0])
                    entry_pathway.append((compound_id, pathwayid))
        print(f"Processed: {compound_id}")
        progress_bar(counter, len(dfcompounds['compound_id']))
    except requests.exceptions.RequestException as e:
        issueIDs.append(compound_id)
        errors_from_requests.append(f"Error for {compound_id}: {e}")
        print(f"Error for {compound_id}: {e}")



junction1 = pd.DataFrame(entry_class, columns=['compound_id', 'class_id'])
junction2 = pd.DataFrame(entry_superclass, columns=['compound_id', 'superclass_id'])
junction3 = pd.DataFrame(entry_pathway, columns=['compound_id', 'pathway_id'])

junction1.to_csv('/home/school/masters/Scripts/ANPDB/anpdb_compound_class_junction.csv', index=False)
junction2.to_csv('/home/school/masters/Scripts/ANPDB/anpdb_compound_superclass_junction.csv', index=False)
junction3.to_csv('/home/school/masters/Scripts/ANPDB/anpdb_compound_pathway_junction.csv', index=False)

print(errors)
print(errors_from_requests)
print(f"no class: {noclasses}")
print(f"no superclass: {nosuperclasses}")
print(f"no pathway: {nopathways}")
print(f"new classes: {newclasses}")
print(f"new superclasses: {newsuperclasses}")
print(f"new pathways: {newpathways}")
print(f"issues: {issueIDs}")

